-- Whether the registration form asks for a username: required (what every
-- tenant has always done), optional, or generated by the server. The default
-- is constant, so adding the column rewrites no row, and IF NOT EXISTS lets
-- the statements run again to no effect.
ALTER TABLE tenants
  ADD COLUMN IF NOT EXISTS registration_username text NOT NULL DEFAULT 'required';

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'tenants_registration_username_check'
  ) THEN
    ALTER TABLE tenants ADD CONSTRAINT tenants_registration_username_check
      CHECK (registration_username IN ('required', 'optional', 'generated'));
  END IF;
END $$;
